using System.Security.Claims;using Aplicacion.Common;using Aplicacion.Interfaces;using Dominio.DTO.Flota;using GestionAlquileres.Security;using GestionAlquileres.ViewModels.Flota;using Microsoft.AspNetCore.Authentication;using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Logging;
namespace GestionAlquileres.Controllers;
public class FlotaController:Controller
{readonly IFlotaService _s;readonly IWebHostEnvironment _env;readonly ILogger<FlotaController> _logger;public FlotaController(IFlotaService s,IWebHostEnvironment env,ILogger<FlotaController> logger){_s=s;_env=env;_logger=logger;}int Usuario()=>int.TryParse(User.FindFirst(ClaimTypes.NameIdentifier)?.Value,out var id)&&id>0?id:1007;
 static readonly string[] ExtPermitidas={".jpg",".jpeg",".png",".webp",".pdf"};const long MaxAdjuntoBytes=5_000_000;
 static readonly TimeZoneInfo PeruTimeZone=TimeZoneInfo.FindSystemTimeZoneById("SA Pacific Standard Time");
 static JsonResponseRequest<T> Fail<T>(string msg,T? data=default)=>new(){Success=false,Mensaje=msg,Data=data,Errors=new(){msg}};
 static string NormalizarTipoEntidad(string? tipo)=>(tipo??"").Trim().ToUpperInvariant();
 static string CarpetaAdjunto(string tipoEntidad)=>tipoEntidad=="PAGO_CONTRATO"?"pago-contrato":tipoEntidad=="RECIBO"?"recibo":tipoEntidad=="COMBUSTIBLE"?"combustible":"operacion-dia";
 static DateTime CombinarFechaConHoraActual(DateTime fecha){var ahora=DateTime.Now;return new DateTime(fecha.Year,fecha.Month,fecha.Day,ahora.Hour,ahora.Minute,ahora.Second);}
 static DateTime HoyPeru()=>TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow,PeruTimeZone).Date;
 static bool ArchivoPermitido(IFormFile? archivo,out string ext){ext=archivo==null?"":Path.GetExtension(archivo.FileName).ToLowerInvariant();return archivo is{Length:>0}&&archivo.Length<=MaxAdjuntoBytes&&ExtPermitidas.Contains(ext);}
 FlotaUsuarioMobileSesionDto? SesionMobile()=>FlotaMobileAuth.ReadSession(User);
 IActionResult JsonDenied(string msg,int statusCode=401)=>StatusCode(statusCode,new{success=false,message=msg,errors=new[]{msg}});
 IActionResult? ExigirSesionMobile(bool vista=false){if(SesionMobile()!=null)return null;return vista?RedirectToAction(nameof(MobileLogin)):JsonDenied("Inicia sesion mobile para continuar.");}
 async Task<bool> ContratoPermitidoMobileAsync(int idContrato,CancellationToken ct){var sesion=SesionMobile();if(sesion?.IdChofer is not >0||idContrato<=0)return false;var contratos=await _s.ListarContratosActivosPorChoferAsync(sesion.IdChofer.Value,ct);var lista=contratos.Data??new List<FlotaContratoAdminDto>();return contratos.Success&&lista.Any(x=>x.IdContrato==idContrato);}
 async Task<IActionResult?> ValidarContratoMobileAsync(int idContrato,CancellationToken ct){if(await ContratoPermitidoMobileAsync(idContrato,ct))return null;return JsonDenied("Tu sesion mobile no tiene acceso a ese contrato.",403);}
 async Task<List<FlotaContratoAdminDto>> ContratosActivosSesionMobileAsync(CancellationToken ct){var sesion=SesionMobile();if(sesion?.IdChofer is not >0)return new();var contratos=await _s.ListarContratosActivosPorChoferAsync(sesion.IdChofer.Value,ct);return contratos.Success?contratos.Data:new();}
 async Task<(FlotaContratoAdminDto? contrato,IActionResult? denied)> ResolverContratoSesionMobileAsync(int idContrato,CancellationToken ct){var contratos=await ContratosActivosSesionMobileAsync(ct);var contrato=contratos.FirstOrDefault(x=>x.IdContrato==idContrato);if(contrato==null)return (null,JsonDenied("Tu sesion mobile no tiene acceso a ese contrato.",403));return (contrato,null);}
 async Task<IActionResult> GuardarOperacionMobileInternaAsync(FlotaOperacionMobileGuardarDto x,string modo,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;deny=await ValidarContratoMobileAsync(x.IdContrato,ct);if(deny!=null)return deny;var hoyPeru=HoyPeru();if(x.Fecha.Date>hoyPeru)return Json(Fail("No puedes registrar una fecha posterior al dia actual en Peru.",new FlotaResultadoDto()));var sesion=SesionMobile();x.ModoRegistro=modo;x.FlgTrabajo="S";x.FlgCobrable="S";x.CodMotivo="TRA";if(modo=="I"){x.KmFinal=null;x.FechaHoraFin=null;x.FechaHoraInicio ??= CombinarFechaConHoraActual(x.Fecha);}else{x.FechaHoraFin ??= CombinarFechaConHoraActual(x.Fecha);}/* TODO: Administracion revisa/corrige estado final, cobrabilidad y motivo. */var result=await _s.GuardarOperacionMobileAsync(Usuario(),x,ct);if(sesion!=null&&result.Success)result.Mensaje="Registro enviado. Administracion podra revisar si corresponde cobrar o descontar.";return Json(result);}
 async Task<int?> ResolverContratoEntidadMobileAsync(string tipoEntidad,int idEntidad,CancellationToken ct){tipoEntidad=NormalizarTipoEntidad(tipoEntidad);return tipoEntidad switch{"OPERACION_DIA"=>await _s.ObtenerContratoPorOperacionDiaAsync(idEntidad,ct),"PAGO_CONTRATO"=>await _s.ObtenerContratoPorPagoContratoAsync(idEntidad,ct),"COMBUSTIBLE"=>await _s.ObtenerContratoPorCombustibleAsync(idEntidad,ct),_=>null};}
