 [HttpGet]public IActionResult MobileLogin(){if(SesionMobile()!=null)return RedirectToAction(nameof(EstacionMobile));return View(new FlotaMobileLoginViewModel());}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> MobileLogin([FromBody]FlotaMobileLoginDto x,CancellationToken ct){var telefono=(x.Telefono??"").Trim();var result=await _s.LoginMobileAsync(x,ct);if(!result.Success){_logger.LogWarning("Flota mobile login fallido. Telefono={Telefono} IsHttps={IsHttps} ForwardedProto={ForwardedProto} Mensaje={Mensaje}",telefono,Request.IsHttps,Request.Headers["X-Forwarded-Proto"].ToString(),result.Mensaje);return Json(result);}var sesion=result.Data??new FlotaUsuarioMobileSesionDto();await HttpContext.SignInAsync(FlotaMobileAuth.Scheme,FlotaMobileAuth.CreatePrincipal(sesion),new AuthenticationProperties{IsPersistent=true,AllowRefresh=true,ExpiresUtc=DateTimeOffset.UtcNow.AddDays(30)});_logger.LogInformation("Flota mobile login correcto. Telefono={Telefono} IdUsuarioMobile={IdUsuarioMobile} IdChofer={IdChofer} IsHttps={IsHttps} ForwardedProto={ForwardedProto} CookieSecurePolicy=SameAsRequest",telefono,sesion.IdUsuarioMobile,sesion.IdChofer,Request.IsHttps,Request.Headers["X-Forwarded-Proto"].ToString());return Json(new{success=true,message="Ingreso correcto.",data=new{redirectUrl=Url.Action(nameof(EstacionMobile),"Flota"),sesion}});}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> MobileLogout(){await HttpContext.SignOutAsync(FlotaMobileAuth.Scheme);return Json(new{success=true,message="Sesion cerrada.",data=new{redirectUrl=Url.Action(nameof(MobileLogin),"Flota")}});}
 // TODO: No exponer endpoints mobile publicamente sin login/sesion/PIN/token real.
 [HttpGet]public async Task<IActionResult> EstacionMobile(CancellationToken ct){var deny=ExigirSesionMobile(true);if(deny!=null)return deny;var sesion=SesionMobile();var hoyPeru=HoyPeru();var contratos=await ContratosActivosSesionMobileAsync(ct);var idAuto=contratos.Count==1?contratos[0].IdContrato:(int?)null;return View(new FlotaEstacionMobileViewModel{FechaOperacionInicial=hoyPeru,FechaOperacionMaxima=hoyPeru,EsSesionMobile=sesion!=null,NombreSesion=sesion?.Nombre??"",TelefonoSesion=sesion?.Telefono??"",IdContratoAsignado=idAuto,PuedeCambiarContrato=contratos.Count>1,PuedeOperar=contratos.Count>0,MensajeContrato=contratos.Count switch{0=>"No tiene contrato activo asignado. Comuniquese con administracion.",1=>"",_=>"Se encontraron varios contratos activos para tu chofer. Selecciona el correcto para operar."},TabInicial="intervalos"});}
 [HttpGet]public async Task<IActionResult> EstacionMobileContratos(CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var contratos=await ContratosActivosSesionMobileAsync(ct);return Json(new JsonResponseRequest<FlotaEstacionMobileDto>{Success=true,Mensaje="",Data=new FlotaEstacionMobileDto{Contratos=contratos,FechaOperacion=HoyPeru()}});}
 [HttpGet]public async Task<IActionResult> MobileResumenGlobal(CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var sesion=SesionMobile();if(sesion?.IdChofer is not >0)return Json(Fail("No se pudo identificar el chofer mobile.",new FlotaChoferResumenGlobalMobileDto()));return Json(await _s.ObtenerResumenGlobalMobileAsync(sesion.IdChofer.Value,ct));}
