 [HttpGet]public async Task<IActionResult> OperacionMobileDetalle(int idContrato,DateTime? fecha,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;deny=await ValidarContratoMobileAsync(idContrato,ct);if(deny!=null)return deny;var hoyPeru=HoyPeru();var fechaConsulta=(fecha??hoyPeru).Date;if(fechaConsulta>hoyPeru)fechaConsulta=hoyPeru;return Json(await _s.ObtenerOperacionMobileAsync(new FlotaOperacionMobileConsultaDto{IdContrato=idContrato,Fecha=fechaConsulta},ct));}
 [HttpGet]public async Task<IActionResult> MobileIntervalosDia(int idContrato,DateTime? fecha,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var hoyPeru=HoyPeru();var fechaOperativa=(fecha??hoyPeru).Date;if(fechaOperativa>hoyPeru)fechaOperativa=hoyPeru;var resolved=await ResolverContratoSesionMobileAsync(idContrato,ct);if(resolved.denied!=null)return resolved.denied;var contrato=resolved.contrato!;return Json(await _s.ListarIntervalosDiaMobileAsync(contrato.IdContrato,contrato.IdChofer,contrato.IdVehiculo,fechaOperativa,ct));}
 [HttpGet]public async Task<IActionResult> MobileResumenHorasDia(int idContrato,DateTime? fecha,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var hoyPeru=HoyPeru();var fechaOperativa=(fecha??hoyPeru).Date;if(fechaOperativa>hoyPeru)fechaOperativa=hoyPeru;var resolved=await ResolverContratoSesionMobileAsync(idContrato,ct);if(resolved.denied!=null)return resolved.denied;var contrato=resolved.contrato!;return Json(await _s.ObtenerResumenHorasMobileAsync(contrato.IdContrato,contrato.IdChofer,contrato.IdVehiculo,fechaOperativa,ct));}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> MobileIntervaloAbrir([FromBody]FlotaIntervaloAbrirRequestDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var resolved=await ResolverContratoSesionMobileAsync(x.IdContrato,ct);if(resolved.denied!=null)return resolved.denied;var contrato=resolved.contrato!;if(x.FechaHoraInicio>DateTime.Now.AddMinutes(1))return Json(Fail("No puedes registrar un inicio futuro.",new FlotaResultadoDto()));x.IdChofer=contrato.IdChofer;x.IdVehiculo=contrato.IdVehiculo;var result=await _s.AbrirIntervaloMobileAsync(Usuario(),x,ct);if(result.Success)result.Mensaje="Intervalo iniciado. Administracion podra revisar el uso registrado.";return Json(result);}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> MobileIntervaloCerrar([FromBody]FlotaIntervaloCerrarRequestDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var resolved=await ResolverContratoSesionMobileAsync(x.IdContrato,ct);if(resolved.denied!=null)return resolved.denied;var contrato=resolved.contrato!;if(x.FechaHoraFin>DateTime.Now.AddMinutes(1))return Json(Fail("No puedes registrar un cierre futuro.",new FlotaResultadoDto()));x.IdChofer=contrato.IdChofer;x.IdVehiculo=contrato.IdVehiculo;var result=await _s.CerrarIntervaloMobileAsync(Usuario(),x,ct);if(result.Success)result.Mensaje="Intervalo cerrado. Administracion podra revisar el estado final del dia.";return Json(result);}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> MobileIntervaloAnular([FromBody]FlotaIntervaloAnularRequestDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;deny=await ValidarContratoMobileAsync(x.IdContrato,ct);if(deny!=null)return deny;return Json(await _s.AnularIntervaloMobileAsync(Usuario(),x,ct));}
