 [HttpGet]public async Task<IActionResult> CombustiblesPorFecha(int idContrato,DateTime? fecha,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;deny=await ValidarContratoMobileAsync(idContrato,ct);if(deny!=null)return deny;var hoyPeru=HoyPeru();var fechaConsulta=(fecha??hoyPeru).Date;if(fechaConsulta>hoyPeru)fechaConsulta=hoyPeru;return Json(await _s.ListarCombustiblePorContratoFechaAsync(idContrato,fechaConsulta,ct));}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> RegistrarCombustible([FromBody]FlotaCombustibleRegistrarDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;deny=await ValidarContratoMobileAsync(x.IdContrato,ct);if(deny!=null)return deny;if(x.Fecha.Date>HoyPeru())return Json(Fail("No puedes registrar combustible con una fecha posterior al dia actual en Peru.",new FlotaResultadoDto()));return Json(await _s.RegistrarCombustibleOperacionAsync(Usuario(),x,ct));}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> AnularCombustible([FromBody]FlotaCombustibleAnularDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var idContrato=await _s.ObtenerContratoPorCombustibleAsync(x.IdCombustibleOperacion,ct);if(!idContrato.HasValue)return JsonDenied("Carga de combustible no encontrada.",404);deny=await ValidarContratoMobileAsync(idContrato.Value,ct);if(deny!=null)return deny;return Json(await _s.AnularCombustibleOperacionAsync(Usuario(),x,ct));}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> RegistrarPagoContrato([FromBody]FlotaPagoContratoRegistrarDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;deny=await ValidarContratoMobileAsync(x.IdContrato,ct);if(deny!=null)return deny;if(x.FechaPago.Date>HoyPeru())return Json(Fail("No puedes registrar un pago con una fecha posterior al dia actual en Peru.",new FlotaResultadoDto()));return Json(await _s.RegistrarPagoContratoAsync(Usuario(),x,ct));}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> EditarPagoContratoMobile([FromBody]FlotaPagoContratoEditarMobileDto x,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var idContrato=await _s.ObtenerContratoPorPagoContratoAsync(x.IdPagoContrato,ct);if(!idContrato.HasValue)return JsonDenied("Pago declarado no encontrado.",404);deny=await ValidarContratoMobileAsync(idContrato.Value,ct);if(deny!=null)return deny;if(x.FechaPago.Date>HoyPeru())return Json(Fail("No puedes registrar un pago con una fecha posterior al dia actual en Peru.",new FlotaResultadoDto()));return Json(await _s.EditarPagoContratoMobileAsync(Usuario(),x,ct));}
