 [HttpGet]public async Task<IActionResult> AdjuntosFlota(string tipoEntidad,int idEntidad,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;var sesion=SesionMobile();if(sesion!=null){var idContrato=await ResolverContratoEntidadMobileAsync(tipoEntidad,idEntidad,ct);if(!idContrato.HasValue)return JsonDenied("Adjunto o entidad no permitida para mobile.",403);deny=await ValidarContratoMobileAsync(idContrato.Value,ct);if(deny!=null)return deny;}return Json(await _s.ListarAdjuntosFlotaAsync(tipoEntidad,idEntidad,ct));}
