 [HttpPost][ValidateAntiForgeryToken][RequestSizeLimit(6_000_000)]public async Task<IActionResult> SubirAdjuntoFlota([FromForm]FlotaAdjuntoRegistrarDto x,IFormFile? archivo,CancellationToken ct){var deny=ExigirSesionMobile();if(deny!=null)return deny;x.TipoEntidad=NormalizarTipoEntidad(x.TipoEntidad);var sesion=SesionMobile();if(sesion!=null){var idContrato=await ResolverContratoEntidadMobileAsync(x.TipoEntidad,x.IdEntidad,ct);if(!idContrato.HasValue)return JsonDenied("No puedes adjuntar archivos a esa entidad.",403);deny=await ValidarContratoMobileAsync(idContrato.Value,ct);if(deny!=null)return deny;}if(archivo is null||archivo.Length<=0)return Json(Fail("Selecciona un archivo.",new FlotaResultadoDto()));if(!ArchivoPermitido(archivo,out var ext))return Json(Fail("Archivo invalido. Usa JPG, PNG, WEBP o PDF de hasta 5 MB.",new FlotaResultadoDto()));var carpeta=CarpetaAdjunto(x.TipoEntidad);var dir=Path.Combine(_env.WebRootPath,"uploads","flota",carpeta);Directory.CreateDirectory(dir);var name=$"{carpeta}_{Guid.NewGuid():N}{ext}";var fullPath=Path.Combine(dir,name);var relativePath=$"/uploads/flota/{carpeta}/{name}";try{await using(var fs=System.IO.File.Create(fullPath)){await archivo.CopyToAsync(fs,ct);}x.RutaArchivo=relativePath;x.NombreOriginal=Path.GetFileName(archivo.FileName);x.MimeType=string.IsNullOrWhiteSpace(archivo.ContentType)?null:archivo.ContentType;x.TamanoBytes=archivo.Length;var result=await _s.RegistrarAdjuntoFlotaAsync(Usuario(),x,ct);if(!result.Success&&System.IO.File.Exists(fullPath))System.IO.File.Delete(fullPath);return Json(result);}catch(Exception ex){if(System.IO.File.Exists(fullPath))System.IO.File.Delete(fullPath);return Json(Fail($"No se pudo registrar el adjunto. {ex.Message}",new FlotaResultadoDto()));}}
 [HttpPost][ValidateAntiForgeryToken][RequestSizeLimit(6_000_000)]public async Task<IActionResult> RegistrarPago([FromForm]FlotaPagoReciboDto x,IFormFile? voucher,CancellationToken ct){if(voucher is{Length:>0}){var ext=Path.GetExtension(voucher.FileName).ToLowerInvariant();if(voucher.Length>5_000_000||!new[]{".jpg",".jpeg",".png",".webp",".pdf"}.Contains(ext))return BadRequest(new{success=false,message="Voucher invalido. Usa imagen o PDF de hasta 5 MB."});var dir=Path.Combine(_env.WebRootPath,"uploads","flota","vouchers");Directory.CreateDirectory(dir);var name=$"voucher_{DateTime.Now:yyyyMMddHHmmss}_{Guid.NewGuid():N}{ext}";await using var fs=System.IO.File.Create(Path.Combine(dir,name));await voucher.CopyToAsync(fs,ct);x.FotoVoucher=$"/uploads/flota/vouchers/{name}";}return Json(await _s.RegistrarPagoAsync(Usuario(),x,ct));}
